// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialOwner;

    function setUp() public {
        c = new C();
        // give the contract a deterministic, reachable owner (mid-range address)
        initialOwner = address(uint160(500));
        vm.prank(address(0)); // contract starts with owner == address(0)
        c.transferOwnership(initialOwner);
    }

    function testFuzz_property(uint256 id, address newOwner) public {
        // wide, small domain so the fuzzer can legitimately pick the rightful owner
        uint256 bounded = bound(id, 0, 1000);
        address actor = address(uint160(bounded));
        // choose a newOwner distinct from the current owner so success is observable
        vm.assume(newOwner != initialOwner);

        bool ok;
        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: if the call succeeded, ownership was transferred to newOwner;
        // if it reverted, ownership is unchanged. The buggy modifier reverts even for
        // the rightful owner, so a successful call leaves owner != newOwner there.
        assertTrue(!ok ? c.owner() == initialOwner : c.owner() == newOwner);
    }
}
